对关键字序列 `{44, 36, 23, 35, 52, 73, 90, 58}` 建立哈希表，哈希函数为 `h(k)=k%7`，执行下面的 `Insert` 函数，则等概率情况下的平均成功查找长度（即查找成功时的关键字比较次数的均值）为（ ）。

```cpp
#include <iostream>
#include <string>
#include <cmath>
#include <vector>
using namespace std;

typedef struct Node{
    int data;
    struct Node *next;
}Node;
Node* hTab[7];
int key[]={44, 36, 23, 35, 52, 73, 90, 58, 0};
void Insert()
{
    int i,j;
    Node *x;

    for(i=0; key[i];i++){
        j = key[i] % 7;
        x=new Node;
        x->data = key[i];
        x->next = hTab[j];
        hTab[j] = x;
    }

    return;
}
```

