#include <iostream>
#include <cstring>
#include <vector>

using namespace std;

const int max_n = 1e5 + 10;

int n;
vector<int> edge[max_n];
int val[max_n];

int min_dist[max_n];
int queue[max_n], qh, qt;

void bfs(int src) {
    qh = qt = 0;
    memset(min_dist, 127, sizeof(min_dist));
    queue[++qt] = src;
    min_dist[src] = 0;
    while (qh < qt) {
        int u = queue[++qh];
        for (auto v: edge[u]) {
            if (min_dist[u] + 1 < min_dist[v]) {
                min_dist[v] = min_dist[u] + 1;
                queue[++qt] = v;
            }
        }
    }
}

int main() {
    int m, src, dst;
    ios::sync_with_stdio(false);
    cin >> n >> m >> src >> dst;
    for (int i = 0; i < n; ++i) {
        cin >> val[i];
    }
    for (int i = 0; i < m; ++i) {
        int x, y;
        cin >> x >> y;
        edge[x].push_back(y);
    }

    bfs(src);
    if (min_dist[dst] > n) {
        cout << "No solution\n";
    }
    else {
        cout << min_dist[dst] - val[src] + val[dst] << '\n';
    }

    return 0;
}

#include <iostream>
#include <cstring>
#include <vector>

using namespace std;

const int max_n = 1005;

int n;
int a[max_n], b[max_n], c[max_n];

int dp[3][max_n];

int result(int x, int y) {
    if (x == y + 1 || x == y - 2) return 2;
    if (x == y) return 1;
    return 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin >> n;
    for (int i = 1; i <= n; ++i) cin >> a[i];
    for (int i = 1; i < n; ++i) cin >> b[i];
    for (int i = 1; i <= n; ++i) cin >> c[i];
    memset(dp, 128, sizeof(dp));
    for (int k = 0; k < 3; ++k){
        dp[k][0] = result(k, c[1]) * a[1];
    }
    for (int i = 2; i <= n; ++i)
        for (int j = i - 1; j >= 0; --j)
            for (int k = 0; k < 3; ++k) {
                int curr_score = result(k, c[i]) * a[i];
                dp[k][j] = dp[k][j] + curr_score;
                if (j > 0) {
                    for (int l = 0; l < 3; ++l) {
                        dp[k][j] = max(dp[k][j], dp[l][j - 1] + curr_score - b[j]);
                    }
                }
            }
    int ans = -2e9, x = 0;
    for (int j = 0; j < n; ++j)
        for (int k = 0; k < 3; ++k) {
            ans = max(ans, dp[k][j]);
        }
    cout << ans << '\n';
    return 0;
}
